CREATE TABLE "${primehrSchema}".succession_governance_policy (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_succ_policy_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".succession_governance_policy_version (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,policy_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),legal_basis VARCHAR(2000) NOT NULL,policy_reference VARCHAR(250) NOT NULL,privacy_notice VARCHAR(4000) NOT NULL,eligibility_guidance VARCHAR(4000) NOT NULL,evidence_requirements VARCHAR(4000) NOT NULL,review_interval_months INTEGER NOT NULL,membership_validity_months INTEGER NOT NULL,minimum_aggregate_cohort INTEGER NOT NULL,requires_employee_notice BOOLEAN NOT NULL,requires_employee_consent BOOLEAN NOT NULL,allows_self_expression BOOLEAN NOT NULL,requires_committee_review BOOLEAN NOT NULL,requires_agency_head_decision BOOLEAN NOT NULL,status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_policy_root FOREIGN KEY(policy_id) REFERENCES "${primehrSchema}".succession_governance_policy(id),CONSTRAINT fk_succ_policy_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".succession_governance_policy_version(id),CONSTRAINT uk_succ_policy_version UNIQUE(agency_id,policy_id,definition_version),CONSTRAINT ck_succ_policy_values CHECK(definition_version>=1 AND review_interval_months>=1 AND membership_validity_months>=1 AND minimum_aggregate_cohort>=3),CONSTRAINT ck_succ_policy_status CHECK(status IN('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_succ_policy_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from),CONSTRAINT ck_succ_policy_lifecycle CHECK((status='DRAFT' AND effective_from IS NULL AND published_at IS NULL) OR (status IN('PUBLISHED','RETIRED') AND effective_from IS NOT NULL AND published_at IS NOT NULL)));
CREATE INDEX ix_succ_policy_effective ON "${primehrSchema}".succession_governance_policy_version(agency_id,status,effective_from,effective_to);
CREATE TABLE "${primehrSchema}".succession_readiness_scale (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_succ_scale_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".succession_readiness_scale_version (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,scale_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),decision_guidance VARCHAR(4000) NOT NULL,requires_narrative BOOLEAN NOT NULL,levels_revision INTEGER NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_scale_root FOREIGN KEY(scale_id) REFERENCES "${primehrSchema}".succession_readiness_scale(id),CONSTRAINT fk_succ_scale_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".succession_readiness_scale_version(id),CONSTRAINT uk_succ_scale_version UNIQUE(agency_id,scale_id,definition_version),CONSTRAINT ck_succ_scale_values CHECK(definition_version>=1 AND levels_revision>=0),CONSTRAINT ck_succ_scale_status CHECK(status IN('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_succ_scale_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from));
CREATE INDEX ix_succ_scale_effective ON "${primehrSchema}".succession_readiness_scale_version(agency_id,status,effective_from,effective_to);
CREATE TABLE "${primehrSchema}".succession_readiness_level (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,scale_version_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,label VARCHAR(200) NOT NULL,description VARCHAR(2000) NOT NULL,development_guidance VARCHAR(4000) NOT NULL,review_after_months INTEGER,allows_pool_membership BOOLEAN NOT NULL,display_order INTEGER NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_level_scale FOREIGN KEY(scale_version_id) REFERENCES "${primehrSchema}".succession_readiness_scale_version(id),CONSTRAINT uk_succ_level_code UNIQUE(agency_id,scale_version_id,normalized_code),CONSTRAINT uk_succ_level_order UNIQUE(agency_id,scale_version_id,display_order),CONSTRAINT ck_succ_level_values CHECK(display_order>=1 AND (review_after_months IS NULL OR review_after_months>=1)));
CREATE INDEX ix_succ_level_scale ON "${primehrSchema}".succession_readiness_level(agency_id,scale_version_id,display_order);
CREATE TABLE "${primehrSchema}".succession_committee_charter (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_succ_charter_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".succession_committee_charter_version (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,charter_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),legal_basis VARCHAR(2000) NOT NULL,authority_reference VARCHAR(250) NOT NULL,quorum_type VARCHAR(20) NOT NULL,quorum_value NUMERIC(7,2) NOT NULL,requires_secretariat BOOLEAN NOT NULL,requires_agency_head_decision BOOLEAN NOT NULL,conflict_declaration_required BOOLEAN NOT NULL,roster_revision INTEGER NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_charter_root FOREIGN KEY(charter_id) REFERENCES "${primehrSchema}".succession_committee_charter(id),CONSTRAINT fk_succ_charter_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".succession_committee_charter_version(id),CONSTRAINT uk_succ_charter_version UNIQUE(agency_id,charter_id,definition_version),CONSTRAINT ck_succ_charter_values CHECK(definition_version>=1 AND roster_revision>=0 AND quorum_value>0 AND (quorum_type<>'PERCENTAGE' OR quorum_value<=100)),CONSTRAINT ck_succ_charter_type CHECK(quorum_type IN('COUNT','PERCENTAGE')),CONSTRAINT ck_succ_charter_status CHECK(status IN('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_succ_charter_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from));
CREATE INDEX ix_succ_charter_effective ON "${primehrSchema}".succession_committee_charter_version(agency_id,status,effective_from,effective_to);
CREATE TABLE "${primehrSchema}".succession_committee_member (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,charter_version_id VARCHAR(36) NOT NULL,employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,display_name VARCHAR(250) NOT NULL,appointment_id BIGINT,job_position_id BIGINT,plantilla_id BIGINT,member_role VARCHAR(30) NOT NULL,voting_member BOOLEAN NOT NULL,effective_from DATE NOT NULL,effective_to DATE,source_fingerprint VARCHAR(120) NOT NULL,source_fetched_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_member_charter FOREIGN KEY(charter_version_id) REFERENCES "${primehrSchema}".succession_committee_charter_version(id),CONSTRAINT uk_succ_member_employee UNIQUE(agency_id,charter_version_id,employee_no),CONSTRAINT ck_succ_member_role CHECK(member_role IN('CHAIR','VICE_CHAIR','MEMBER','SECRETARIAT')),CONSTRAINT ck_succ_member_secretariat CHECK(member_role<>'SECRETARIAT' OR voting_member=FALSE),CONSTRAINT ck_succ_member_dates CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE INDEX ix_succ_member_charter ON "${primehrSchema}".succession_committee_member(agency_id,charter_version_id,member_role);
CREATE TABLE "${primehrSchema}".succession_committee_conflict (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,charter_version_id VARCHAR(36) NOT NULL,declaring_employee_no VARCHAR(100) NOT NULL,related_employee_no VARCHAR(100) NOT NULL,conflict_type VARCHAR(30) NOT NULL,details VARCHAR(2000) NOT NULL,status VARCHAR(20) NOT NULL,declared_by VARCHAR(100) NOT NULL,declared_at TIMESTAMP WITH TIME ZONE NOT NULL,resolved_by VARCHAR(100),resolved_at TIMESTAMP WITH TIME ZONE,resolution_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_succ_conflict_charter FOREIGN KEY(charter_version_id) REFERENCES "${primehrSchema}".succession_committee_charter_version(id),CONSTRAINT ck_succ_conflict_type CHECK(conflict_type IN('PERSONAL','PROFESSIONAL','SUPERVISORY','OTHER')),CONSTRAINT ck_succ_conflict_status CHECK(status IN('ACTIVE','RESOLVED')),CONSTRAINT ck_succ_conflict_people CHECK(declaring_employee_no<>related_employee_no),CONSTRAINT ck_succ_conflict_resolution CHECK((status='ACTIVE' AND resolved_at IS NULL) OR (status='RESOLVED' AND resolved_at IS NOT NULL AND resolution_reason IS NOT NULL)));
CREATE INDEX ix_succ_conflict_charter ON "${primehrSchema}".succession_committee_conflict(agency_id,charter_version_id,status);
